// Rule L8, plan section 11 #19: a GraphFunction becomes a `/// @custom` function whose `UE.` calls stay in its body,
// written the way a `.dss` reads them; both front ends lift them into inputs of the Custom node (`_ds_<Fn>_UE<k>`),
// so the migrated text builds the very nodes the 1.x text builds. The second one stood inside a `Namespace`.
/// @custom
void MgPulse(float2 uv, float Gain, out float pulse)
{
    float t = UE.Time();
    float mixed = UE.Lerp(A = 0.0, B = Gain, Alpha = 0.5);
    pulse = sin(uv.x * 8.0 + t) * mixed;
}

/// @custom
/// @name MgSpace::Texel
void MgSpace_Texel(float scale, out float2 result)
{
    // the size of one texel, scaled
    float2 inv = UE.SceneTexture(SceneTextureId = "SceneColor").InvSize;
    result = inv * scale;
}

/// @name DreamShaderTests/Migrate/M_MgGraphFunction
export void M_MgGraphFunction(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float Alpha = 0;
    float2 uv = UE.TexCoord(Index = 0);
    float First = 0;
    float Second = 0;
    MgPulse(uv, 2.0, First);
    MgPulse(uv, 4.0, Second);
    float2 Size = float2(0, 0);
    MgSpace_Texel(2.0, Size);
    Color = float3(Size, 0.0);
    Alpha = First * Second;
    Base.EmissiveColor = Color;
    Base.Opacity = Alpha;
}
